// Valida antes de consultar fontes externas ou chamar a IA.
const payload = $input.first().json;
const corpo = payload.body ?? payload;
if (!corpo || !Array.isArray(corpo.clientes) || corpo.clientes.length < 1 || corpo.clientes.length > 10) {
  throw new Error('Envie JSON {"clientes":[...]} contendo de 1 a 10 clientes ficticios.');
}
const permitidos = {conservador: 'Conservador', moderado: 'Moderado', arrojado: 'Arrojado'};
const vistos = new Set();
function saldoEmReais(valor) {
  if (typeof valor === 'number') {
    if (Number.isFinite(valor) && valor >= 0) return valor;
    throw new Error('Saldo numerico invalido.');
  }
  const texto = String(valor ?? '').trim();
  if (!texto) throw new Error('Saldo nao informado.');
  // Formatos aceitos: R$ 3.200,00, 3200,00 e 3200.00 (numero decimal simples).
  const limpo = texto.replace(/\s|R\$/gi, '');
  const br = /^\d{1,3}(\.\d{3})*(,\d{1,2})?$/.test(limpo) || /^\d+(,\d{1,2})$/.test(limpo);
  const decimal = /^\d+(\.\d{1,2})?$/.test(limpo);
  if (!br && !decimal) throw new Error('Saldo fora dos formatos esperados: ' + texto);
  const numero = Number(br ? limpo.replace(/\./g, '').replace(',', '.') : limpo);
  if (!Number.isFinite(numero) || numero < 0) throw new Error('Saldo invalido.');
  return numero;
}
const clientes = corpo.clientes.map((c, indice) => {
  if (!c || typeof c !== 'object' || Array.isArray(c)) throw new Error('Cliente invalido na posicao ' + (indice + 1));
  const nome = String(c.nome ?? '').trim();
  const email = String(c.email ?? '').trim().toLowerCase();
  const perfilChave = String(c.perfil ?? '').trim().toLowerCase();
  if (!nome || nome.length > 100 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error('Nome ou e-mail ficticio invalido na posicao ' + (indice + 1));
  }
  if (!permitidos[perfilChave]) throw new Error('Perfil deve ser Conservador, Moderado ou Arrojado.');
  if (vistos.has(email)) throw new Error('E-mail duplicado no mesmo lote: ' + email);
  vistos.add(email);
  return {nome, email, perfil: permitidos[perfilChave], saldo: saldoEmReais(c.saldo)};
});
return [{json:{clientes, quantidade_clientes:clientes.length, origem:'DIO - dados ficticios'}}];

// O CSV original da DIO possui 4 colunas e nenhum campo com virgula entre aspas.
const texto = $input.first().json.csv_texto;
if (typeof texto !== 'string' || !texto.trim()) throw new Error('A consulta ao CSV nao retornou texto.');
const linhas = texto.replace(/\r\n?/g, '\n').split('\n').map(s => s.trim()).filter(Boolean);
const cabecalho = linhas.shift()?.replace(/^\uFEFF/, '').toLowerCase();
if (cabecalho !== 'perfil,produto,minimo,rentabilidade') throw new Error('Cabecalho CSV inesperado: '+cabecalho);
const nomes = new Set();
const perfis = new Set(['conservador', 'moderado', 'arrojado']);
const produtos = linhas.map((linha, indice) => {
  const campos = linha.split(',').map(s => s.trim());
  if (campos.length !== 4) throw new Error('Linha CSV '+(indice+2)+' invalida.');
  const [perfil, produto, minimoBruto, rentabilidade] = campos;
  const minimo = Number(minimoBruto);
  if (!perfis.has(perfil.toLowerCase()) || !produto || !Number.isFinite(minimo) || minimo < 0) {
    throw new Error('Produto ou minimo invalido na linha '+(indice+2));
  }
  const key = perfil.toLowerCase()+'|'+produto.toLowerCase();
  if (nomes.has(key)) throw new Error('Produto repetido no CSV: '+produto);
  nomes.add(key);
  return {perfil, produto, minimo, rentabilidade};
});
if (!produtos.length) throw new Error('Nenhum produto encontrado no CSV.');
return [{json:{produtos, quantidade_produtos:produtos.length}}];

const clientes = $('Validar clientes').first().json.clientes;
const produtos = $input.first().json.produtos;
if (!Array.isArray(clientes) || !Array.isArray(produtos)) throw new Error('Clientes ou produtos ausentes.');
const brl = valor => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(valor);
return clientes.map((cliente, i) => {
  const elegiveis = produtos.filter(p => p.perfil.toLowerCase() === cliente.perfil.toLowerCase() && p.minimo <= cliente.saldo)
    .map(p => ({produto:p.produto, minimo:p.minimo, rentabilidade_ilustrativa:p.rentabilidade}));
  return {json:{
    numero:i+1, nome:cliente.nome, email:cliente.email, perfil:cliente.perfil,
    saldo:cliente.saldo, saldo_formatado:brl(cliente.saldo),
    opcoes_elegiveis:elegiveis, quantidade_opcoes:elegiveis.length,
    fonte_produtos:'https://digitalinnovationone.github.io/dio-lab-assistente-investimentos-rpa-n8n/data.csv'
  }};
});

// O texto definitivo sobre produtos sera montado em codigo, nao inventado pela IA.
const descricaoPerfil = {
  Conservador:'Este perfil costuma priorizar previsibilidade e preservacao.',
  Moderado:'Este perfil busca ponderar estabilidade e oscilacoes.',
  Arrojado:'Este perfil admite, em geral, maior variacao.'
};
return $input.all().map(item=>({json:{
  ...item.json,
  contexto_perfil:descricaoPerfil[item.json.perfil]||'Perfil declarado no cadastro.',
  saudacao_padrao:`Olá, ${item.json.nome}! Aqui está o resumo educativo da sua simulação com dados fictícios.`
}}));

