// Os fatos financeiros da resposta sao montados por regras deterministicas a partir do CSV.
const base = $('Preparar contexto').all();
const respostas = $input.all();
if (respostas.length !== base.length) throw new Error('Numero de respostas da IA diferente do numero de clientes.');
const aviso = 'Simulação educativa com dados fictícios; não é recomendação de investimento.';
const brl = valor => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(valor);
return respostas.map((item, i) => {
  const c = base[i].json;
  const entrada = item.json ?? {};
  const bruto = String(entrada.text ?? entrada.output ?? '').trim().replace(/\s+/g,' ');
  // Bloqueio basico de saidas suspeitas: mensagens com taxas, URLs ou linguagem de recomendacao.
  const invalida = !bruto || bruto.length > 450 || /(?:\b\d+(?:[.,]\d+)?\s*%|https?:\/\/|\b(?:compre|invista|recomendo|garantid[oa]|rentabilidade|retorno|lucro)\b)/i.test(bruto);
  const intro = invalida ? c.saudacao_padrao : bruto;
  const lista = c.opcoes_elegiveis.length
    ? c.opcoes_elegiveis.map(p => `- ${p.produto} (aporte mínimo fictício: ${brl(p.minimo)})`).join('\n')
    : 'Nenhuma opção da base atende aos critérios do perfil e saldo informados.';
  const mensagem = [intro, `Perfil declarado: ${c.perfil}. Saldo fictício: ${c.saldo_formatado}.`,
    'Produtos do CSV didático com perfil correspondente e aporte mínimo compatível:', lista, aviso].join('\n\n');
  return {json:{
    numero:c.numero, nome:c.nome, email:c.email, perfil:c.perfil, saldo:c.saldo,
    opcoes_elegiveis:c.opcoes_elegiveis, quantidade_opcoes:c.quantidade_opcoes,
    mensagem, texto_ia:invalida?null:bruto,
    modo_mensagem: invalida?'fallback_estatico':'gemini_com_dados_deterministicos',
    observacao_ia:entrada.error ? 'Falha da API Gemini; usada mensagem estatica.' :
      (invalida ? 'Resposta da IA indisponivel ou rejeitada na validacao basica.' : 'Texto da IA aceito na validacao basica.'),
    fonte_produtos:c.fonte_produtos
  }};
});
